mapper.select:
SELECT a.AREA_DSCR, COALESCE(CONCAT(TO_CHAR(ROUND(CAST(NULLIF(((v.INDEX_VALUE/ ${params.AMT_UNIT}))::text, '') AS NUMERIC), 2), 'FM999,999,999,999,999,999,999,999,990.00'),' '),'') AS INDEX_VALUE, COALESCE(CONCAT(TO_CHAR(ROUND(CAST(NULLIF(((v.INDEX_VALUE_2/ ${params.AMT_UNIT}))::text, '') AS NUMERIC), 2), 'FM999,999,999,999,999,999,999,999,990.00'),' '),'') AS INDEX_VALUE_2, COALESCE(CONCAT(TO_CHAR(ROUND(CAST(NULLIF(((v.INDEX_VALUE_3 / ${params.AMT_UNIT}))::text, '') AS NUMERIC), 2), 'FM999,999,999,999,999,999,999,999,990.00'),' '),'') AS INDEX_VALUE_3 FROM report.area_sort a LEFT JOIN ( select AREA_DSCR, SUM(c.INDEX_VALUE) AS INDEX_VALUE, SUM(c.INDEX_VALUE_2) AS INDEX_VALUE_2, SUM(c.INDEX_VALUE_3) AS INDEX_VALUE_3 from ( SELECT a.INDEX_DIM_CODE, a.INDEX_VALUE AS INDEX_VALUE, 0 AS INDEX_VALUE_2, 0 AS INDEX_VALUE_3 FROM indicators_lib.lib_indicators_00017601 a
WHERE a.DIMENSION_FLAG = '2' AND a.PERIOD_FLAG = '3' and a.ACCOUNT_PERIOD ='${params.ACCOUNT_PERIOD}'
union all SELECT a.INDEX_DIM_CODE, 0 AS INDEX_VALUE, a.INDEX_VALUE AS INDEX_VALUE_2, 0 AS INDEX_VALUE_3 FROM indicators_lib.lib_indicators_00017604 a WHERE a.DIMENSION_FLAG = '2' AND a.PERIOD_FLAG = '3' and a.ACCOUNT_PERIOD ='${params.ACCOUNT_PERIOD}'
union all SELECT a.INDEX_DIM_CODE, 0 AS INDEX_VALUE, 0 AS INDEX_VALUE_2, a.INDEX_VALUE AS INDEX_VALUE_3 FROM indicators_lib.lib_indicators_00017602 a WHERE a.DIMENSION_FLAG = '2' AND a.PERIOD_FLAG = '3' and a.ACCOUNT_PERIOD ='${params.ACCOUNT_PERIOD}'
) c LEFT JOIN report.area_sort b ON c.INDEX_DIM_CODE = b.AREA_NO_ID where b.area_dscr IS NOT NULL group by c.INDEX_DIM_CODE
) v ON a.area_dscr=v.AREA_DSCR ORDER BY a.area_no_id,v.INDEX_VALUE DESC

SELECT a.AREA_DSCR, COALESCE(CONCAT(TO_CHAR(ROUND(CAST(NULLIF(((v.INDEX_VALUE/ ${params.AMT_UNIT}))::text, '') AS NUMERIC), 2), 'FM999,999,999,999,999,999,999,999,990.00'),' '),'') AS INDEX_VALUE, COALESCE(CONCAT(TO_CHAR(ROUND(CAST(NULLIF(((v.INDEX_VALUE_2/ ${params.AMT_UNIT}))::text, '') AS NUMERIC), 2), 'FM999,999,999,999,999,999,999,999,990.00'),' '),'') AS INDEX_VALUE_2, COALESCE(CONCAT(TO_CHAR(ROUND(CAST(NULLIF(((v.INDEX_VALUE_3 / ${params.AMT_UNIT}))::text, '') AS NUMERIC), 2), 'FM999,999,999,999,999,999,999,999,990.00'),' '),'') AS INDEX_VALUE_3 FROM report.area_sort a LEFT JOIN ( select AREA_DSCR, SUM(c.INDEX_VALUE) AS INDEX_VALUE, SUM(c.INDEX_VALUE_2) AS INDEX_VALUE_2, SUM(c.INDEX_VALUE_3) AS INDEX_VALUE_3 from ( SELECT a.INDEX_DIM_CODE, a.INDEX_VALUE AS INDEX_VALUE, 0 AS INDEX_VALUE_2, 0 AS INDEX_VALUE_3 FROM indicators_lib.lib_indicators_00017601 a
WHERE a.DIMENSION_FLAG = '2' AND a.PERIOD_FLAG = '3' and a.ACCOUNT_PERIOD ='${params.ACCOUNT_PERIOD}'
union all SELECT a.INDEX_DIM_CODE, 0 AS INDEX_VALUE, a.INDEX_VALUE AS INDEX_VALUE_2, 0 AS INDEX_VALUE_3 FROM indicators_lib.lib_indicators_00017604 a WHERE a.DIMENSION_FLAG = '2' AND a.PERIOD_FLAG = '3' and a.ACCOUNT_PERIOD ='${params.ACCOUNT_PERIOD}'
union all SELECT a.INDEX_DIM_CODE, 0 AS INDEX_VALUE, 0 AS INDEX_VALUE_2, a.INDEX_VALUE AS INDEX_VALUE_3 FROM indicators_lib.lib_indicators_00017602 a WHERE a.DIMENSION_FLAG = '2' AND a.PERIOD_FLAG = '3' and a.ACCOUNT_PERIOD ='${params.ACCOUNT_PERIOD}'
) c LEFT JOIN report.area_sort b ON c.INDEX_DIM_CODE = b.AREA_NO_ID where b.area_dscr IS NOT NULL group by c.INDEX_DIM_CODE
) v ON a.area_dscr=v.AREA_DSCR ORDER BY a.area_no_id,v.INDEX_VALUE DESC
